select
videoComment.*,
videos.video_name,
videos.banner_img,
videoUser.nick_name,
videoUser.head_img,
s.nick_name as nickNameTo,
s.head_img as headerImgTo
from video_comment videoComment
left join videos videos on videoComment.videos_id = videos.id
left join video_user videoUser on videoComment.user_id = videoUser.id
left join (select * from video_user) s on s.id = videoComment.to_user_id

    and videoComment.id = #{id}
    and videoComment.parent_id = #{parentId}
    and videoComment.comment_info = #{commentInfo}
    and videoComment.user_id = #{userId} or videoComment.to_user_id = #{userId}
    and videoComment.videos_id = #{videosId}
    and videoComment.create_time = #{createTime}
    and videos.video_name like concat('%',#{videoName},'%')
    and videos.banner_img = #{bannerImg}
    and videoUser.nick_name like concat('%',#{nickName},'%')
    and videoUser.head_img = #{headImg}

order by create_time desc

    limit #{current},#{pageSize}

select count(*) from video_comment videoComment
left join videos videos on videoComment.videos_id = videos.id
left join video_user videoUser on videoComment.user_id = videoUser.id
left join (select * from video_user) s on s.id = videoComment.to_user_id

    and videoComment.id = #{id}
    and videoComment.parent_id = #{parentId}
    and videoComment.comment_info = #{commentInfo}
    and videoComment.user_id = #{userId}
    and videoComment.videos_id = #{videosId}
    and videoComment.create_time = #{createTime}
    and videos.video_name like concat('%',#{videoName},'%')
    and videos.banner_img = #{bannerImg}
    and videoUser.nick_name like concat('%',#{nickName},'%')
    and videoUser.head_img = #{headImg}
